sed -n '105,140p' tests/codegen/callables/closure_array_returns.rs: l_of_mixed_params() { let out = compile_and_run( r#"<?php class Box { public function pair(mixed $a, mixed $b) { return [$a, $b]; } public static function spair(mixed $a, mixed $b) { return [$a, $b]; } } var_dump((new Box())->pair(1, "z")); var_dump(Box::spair("z", 1)); "#, ); assert_eq!( out, "array(2) {
 [0]=>
 int(1)
 [1]=>
 string(1) "z"
}
\ array(2) {
 [0]=>
 string(1) "z"
 [1]=>
 int(1)
}
" ); } /// Verifies a by-value captured string survives the returned literal. `$argc` keeps the /// capture runtime-unknown so constant propagation cannot fold it into the literal. #[test] fn test_closure_returns_array_literal_with_by_value_capture() { let out = compile_and_run( r#"<?php $tag = str_repeat("v", $argc); $f = function (mixed $a) use ($tag) { return [$a, $tag]; }; var_dump($f(1)); "#, ); assert_eq!( out, "array(2) {
 [0]=>
 int(1)
 [1]=>
 string(1) "v"
}
" ); }
